namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string InstructorName { get; set; }
    public required string InstructorBio { get; set; }
    public required string DepartmentCode { get; set; }
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public required string Code { get; set; }
    public required string Name { get; set; }
    public required string Description { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z0-9]{6,10}$", ErrorMessage = "Student ID must be 6-10 alphanumeric characters.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics including statistics." },
        new() { Code = "ENG", Name = "English", Description = "Literature, writing, and linguistics." },
        new() { Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Code = "HIST", Name = "History", Description = "Exploration of past events and civilizations." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, Code = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, loops, methods, and object-oriented basics.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She specializes in programming languages and compiler design.", DepartmentCode = "CS", IsFeatured = true },
        new() { Id = 2, Code = "CS201", Title = "Data Structures & Algorithms", Description = "Study fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Prof. James Wright", InstructorBio = "Prof. Wright's research focuses on algorithmic complexity and distributed systems. He has published over 40 papers in top-tier conferences.", DepartmentCode = "CS", IsFeatured = true },
        new() { Id = 3, Code = "CS310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, indexing, transactions, and an introduction to NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez worked in industry for a decade at major cloud providers before joining academia. Her focus is on scalable data systems.", DepartmentCode = "CS", IsFeatured = false },
        new() { Id = 4, Code = "MATH101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Alan Torres", InstructorBio = "Dr. Torres is an award-winning educator who has taught calculus for over 20 years. He is passionate about making mathematics accessible.", DepartmentCode = "MATH", IsFeatured = true },
        new() { Id = 5, Code = "MATH202", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to data science and graphics.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Prof. Emily Park", InstructorBio = "Prof. Park's research bridges pure mathematics and machine learning. She leads the university's data science initiative.", DepartmentCode = "MATH", IsFeatured = false },
        new() { Id = 6, Code = "ENG101", Title = "Composition & Rhetoric", Description = "Develop clear, persuasive writing skills through essays, research papers, and peer review workshops.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Prof. David Nguyen", InstructorBio = "Prof. Nguyen is a published author and rhetoric scholar. His work focuses on digital communication and public discourse.", DepartmentCode = "ENG", IsFeatured = false },
        new() { Id = 7, Code = "ENG220", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, covering major movements and authors.", Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", InstructorName = "Dr. Rachel Kim", InstructorBio = "Dr. Kim specializes in 20th-century American fiction and has received multiple teaching excellence awards.", DepartmentCode = "ENG", IsFeatured = false },
        new() { Id = 8, Code = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions demonstrating core principles.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 3:00–5:00 PM", InstructorName = "Dr. Robert Patel", InstructorBio = "Dr. Patel is an experimental physicist who has worked at CERN. He brings cutting-edge research into the classroom.", DepartmentCode = "PHYS", IsFeatured = true },
        new() { Id = 9, Code = "PHYS210", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Prof. Lisa Okafor", InstructorBio = "Prof. Okafor's research on photonics has been funded by major grants. She mentors undergraduate researchers in her lab.", DepartmentCode = "PHYS", IsFeatured = false },
        new() { Id = 10, Code = "HIST101", Title = "World History to 1500", Description = "Survey of civilizations, empires, and cultures from antiquity through the late medieval period.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Thomas Grant", InstructorBio = "Dr. Grant is an archaeologist and historian who has led excavations across the Mediterranean. He makes ancient history vivid and engaging.", DepartmentCode = "HIST", IsFeatured = false },
        new() { Id = 11, Code = "HIST205", Title = "Modern European History", Description = "Political, social, and cultural developments in Europe from the Enlightenment to the present.", Credits = 3, Schedule = "Tue/Thu 2:30–3:45 PM", InstructorName = "Prof. Anna Müller", InstructorBio = "Prof. Müller is a specialist in 19th-century European political history and has authored three books on the subject.", DepartmentCode = "HIST", IsFeatured = false },
        new() { Id = 12, Code = "CS405", Title = "Machine Learning", Description = "Supervised and unsupervised learning, neural networks, model evaluation, and practical applications using Python.", Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She specializes in programming languages and compiler design.", DepartmentCode = "CS", IsFeatured = true },
    ];

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string code) =>
        _departments.FirstOrDefault(d => d.Code.Equals(code, StringComparison.OrdinalIgnoreCase));

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, string? departmentCode)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentCode))
        {
            query = query.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

