toolArgs.file_text:
@page "/enroll"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Enrollment Request</h1>

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h4 class="alert-heading">Request Submitted!</h4>
            <p>Thank you, <strong>@Model.FullName</strong>. Your enrollment request for
                <strong>@(SelectedCourse?.Code) — @(SelectedCourse?.Title)</strong> has been received.</p>
            <p class="mb-0">You will receive a confirmation via your university email within 2 business days.</p>
        </div>
        <a href="/courses" class="btn btn-primary">Back to Course Catalog</a>
    }
    else
    {
        <p class="text-muted mb-4">Fill out this form to request enrollment in a course. All fields are required.</p>

        <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
            <DataAnnotationsValidator />
            <AntiforgeryToken />

            <div class="row g-3">
                <div class="col-md-6">
                    <label for="fullName" class="form-label">Full Name</label>
                    <InputText id="fullName" @bind-Value="Model.FullName" class="form-control" />
                    <ValidationMessage For="() => Model.FullName" />
                </div>

                <div class="col-md-6">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g. ABC12345" />
                    <ValidationMessage For="() => Model.StudentId" />
                </div>

                <div class="col-12">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in CatalogService.GetAllCourses())
                        {
                            <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.CourseId" />
                </div>

                <div class="col-12">
                    <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                    <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
                </div>
            </div>
        </EditForm>
    }
</div>

@code {
    [SupplyParameterFromForm]
    private UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "courseId")]
    public int? PreselectedCourseId { get; set; }

    private bool IsSubmitted { get; set; }
    private UniversityCourseCatalog.Models.Course? SelectedCourse { get; set; }

    protected override void OnInitialized()
    {
        if (PreselectedCourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = PreselectedCourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        SelectedCourse = CatalogService.GetCourse(Model.CourseId);
        IsSubmitted = true;
    }
}

